use anyhow :: { Context , Result } ; use std :: fs ; use std :: path :: { Path , PathBuf } ; use std :: io :: { BufRead , BufReader } ; use log :: info ; # [doc = " Fast count flake.nix files"] fn count_flake_files_fast (base : & Path) -> Result < usize > { let mut count = 0 ; if ! base . exists () { return Ok (0) ; } let search_dirs = vec ! [base . join ("workspaces") , base . join ("layer1") , base . join ("layer2") ,] ; for search_dir in search_dirs { if search_dir . exists () { for entry in fs :: read_dir (search_dir) ? { if let Ok (entry) = entry { let path = entry . path () ; if path . is_dir () { let flake_path = path . join ("flake.nix") ; if flake_path . exists () { count += 1 ; } let layer1_flake = path . join ("layer1") . join ("flake.nix") ; let layer2_flake = path . join ("layer2") . join ("flake.nix") ; if layer1_flake . exists () { count += 1 ; } if layer2_flake . exists () { count += 1 ; } } } } } } Ok (count) }